(async()=>{if(new URLSearchParams(location.search).get('profile')!=='inventory-check')return;while(!window.EmberQA)await new Promise(r=>setTimeout(r,100));const q=EmberQA;q.apply({...SurvivalData.fresh(),inventory:{wood:24,stone:18,fiber:12,ore:8,crystal:3,berry:9,hammer:1,sword:1,flashlight:1,resin:4,hide:2,fuel:2},quickSlots:['hammer','sword','flashlight',null,null],hand:'hammer'});document.getElementById('welcome').hidden=true;q.setPlaying(true);q.inventory();})();
